from pathlib import Path
from datetime import datetime, timezone
import base64
import hashlib
import html
import json
import os

root = Path.cwd()
base = root / "docs/research/prose-qr/portable-story-2026-10-11"
ledger = json.loads((base / "candidate-ledger.json").read_text())
counts = ledger["counts"]
def image(path):
    return "data:image/png;base64," + base64.b64encode((base/path).read_bytes()).decode()
def link(path):
    return os.path.relpath(root/path,base)
def compact_row(r):
    s = r.get("spec",{})
    structural = r.get("structural") or {}
    return {"batch":r["batch"], "id":r["id"], "status":r.get("status","captured"), "control":r["control"],
        "path":link(r["path"]) if r.get("path") else None, "sha256":r.get("pngSha256"),
        "font":s.get("font","native document"),"size":s.get("fontSize"),
        "field":structural.get("field",s.get("field",structural.get("bodyCssPixels"))),
        "gray":s.get("gray"), "case":s.get("case","preserve"),
        "readers":{e:v["status"] for e,v in r["readers"].items()},
        "two":r["twoSoftwareReadersExact"],"note":r.get("reason",r.get("batchStopReason",""))}
data = json.dumps([compact_row(r) for r in ledger["slots"]+ledger["controls"]],ensure_ascii=False).replace("</","<\\/")
